using System.Collections.Generic;
using UnityEditor;
using UnityEditor.Animations;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;

namespace TrainSim.SceneBuilding
{
    /// <summary>
    /// Editor helpers for the train sim.
    ///
    /// Both scenes are generated by Tools/generate_scenes.py, which builds them from his
    /// SampleScene so the lighting, skybox, rails and signal are his by construction. This file
    /// deliberately does not build scenes any more: two builders would drift apart, and the one
    /// that used to live here produced scene 2 from the asset pack demo scene, which is where
    /// the fog and the broken purple sky came from.
    ///
    /// What is left is the measuring and navigation that is genuinely easier inside Unity.
    /// </summary>
    public static class TrainSimTools
    {
        const string Scene1Path = "Assets/Scenes/SampleScene.unity";
        const string Scene2Path = "Assets/Scenes/Scene2_StationBoarding.unity";

        const string TrainPrefabPath =
            "Assets/Polyeler/Simple Train Pack/Prefabs/Train/Train_Type A.prefab";

        const string RailPrefabPath =
            "Assets/Polyeler/Simple Train Pack/Prefabs/Rail/Straight rail.prefab";

        const string HitogatasModelPath =
            "Assets/pixel horror abandoned rural  train station/Models/Hitogatas.fbx";

        const string StationScenePath =
            "Assets/pixel horror abandoned rural  train station/Scenes/environment with station.unity";

        // ==========================================
        // NAVIGATION
        // ==========================================

        [MenuItem("Tools/Train Sim/Open Scene 1", priority = 0)]
        public static void OpenScene1()
        {
            EditorSceneManager.OpenScene(Scene1Path, OpenSceneMode.Single);
            Debug.Log("[TRAIN SIM] Opened " + Scene1Path);
        }

        [MenuItem("Tools/Train Sim/Open Scene 2", priority = 1)]
        public static void OpenScene2()
        {
            EditorSceneManager.OpenScene(Scene2Path, OpenSceneMode.Single);
            Debug.Log("[TRAIN SIM] Opened " + Scene2Path);
        }

        /// <summary>
        /// Loads scene 1 with scene 2 alongside it for comparing the two. Scene 1 stays active,
        /// so pressing Play still starts the run in.
        /// </summary>
        [MenuItem("Tools/Train Sim/Open Both Scenes", priority = 2)]
        public static void OpenBothScenes()
        {
            Scene one = EditorSceneManager.OpenScene(Scene1Path, OpenSceneMode.Single);
            EditorSceneManager.OpenScene(Scene2Path, OpenSceneMode.Additive);
            SceneManager.SetActiveScene(one);

            Debug.Log(
                "[TRAIN SIM] Both scenes loaded. Scene 1 is active, so Play starts the run in."
            );
        }

        [MenuItem("Tools/Train Sim/Add Scenes To Build Settings", priority = 3)]
        public static void AddScenesToBuildSettings()
        {
            var wanted = new List<EditorBuildSettingsScene>
            {
                new EditorBuildSettingsScene(Scene1Path, true),
                new EditorBuildSettingsScene(Scene2Path, true)
            };

            foreach (var existing in EditorBuildSettings.scenes)
            {
                if (existing.path != Scene1Path &&
                    existing.path != Scene2Path)
                {
                    wanted.Add(existing);
                }
            }

            EditorBuildSettings.scenes = wanted.ToArray();

            Debug.Log("[TRAIN SIM] Scene list now holds " + wanted.Count + " scenes.");
        }

        // ==========================================
        // TUNNEL
        // ==========================================

        // The bore runs along the track at x = 0, through the hill the pack put at z = 63.
        const float TunnelHalfWidth = 5f;
        const float TunnelStartZ = 44f;
        const float TunnelEndZ = 96f;

        /// <summary>
        /// Punches a hole through the terrain along the track so the hill becomes a tunnel the
        /// train can run through, instead of solid rock with the rails buried in it. The pack
        /// supplies the tunnel mouth as a prefab but never cut the ground away behind it.
        ///
        /// This edits stage.asset in place. It is idempotent, and revertible with git.
        /// </summary>
        [MenuItem("Tools/Train Sim/Carve Tunnel Through Terrain", priority = 21)]
        public static void CarveTunnel()
        {
            Terrain terrain = Object.FindFirstObjectByType<Terrain>();

            if (terrain == null)
            {
                // Nothing open, which is the normal case when this runs from the command line.
                EditorSceneManager.OpenScene(Scene1Path, OpenSceneMode.Single);
                terrain = Object.FindFirstObjectByType<Terrain>();
            }

            if (terrain == null || terrain.terrainData == null)
            {
                Debug.LogError("[TRAIN SIM] No terrain found.");
                return;
            }

            TerrainData data = terrain.terrainData;
            Vector3 origin = terrain.transform.position;
            Vector3 size = data.size;

            int res = data.holesResolution;
            bool[,] holes = data.GetHoles(0, 0, res, res);

            int cut = 0;

            for (int y = 0; y < res; y++)
            {
                // Holes are indexed [y, x], with y running along z.
                float worldZ = origin.z + (y / (float)(res - 1)) * size.z;

                if (worldZ < TunnelStartZ || worldZ > TunnelEndZ)
                {
                    continue;
                }

                for (int x = 0; x < res; x++)
                {
                    float worldX = origin.x + (x / (float)(res - 1)) * size.x;

                    if (Mathf.Abs(worldX) > TunnelHalfWidth)
                    {
                        continue;
                    }

                    if (holes[y, x])
                    {
                        holes[y, x] = false;      // false means hole
                        cut++;
                    }
                }
            }

            if (cut == 0)
            {
                Debug.Log("[TRAIN SIM] Tunnel already carved, nothing to do.");
                return;
            }

            Undo.RegisterCompleteObjectUndo(data, "Carve tunnel");
            data.SetHoles(0, 0, holes);
            EditorUtility.SetDirty(data);
            AssetDatabase.SaveAssets();

            Debug.Log(
                "[TRAIN SIM] Carved " + cut + " terrain cells into a tunnel between z " +
                TunnelStartZ + " and z " + TunnelEndZ + "."
            );
        }

        // ==========================================
        // PASSENGER MODEL
        // ==========================================

        const string PassengerModelPath = "Assets/Passengers/Louise@Walking.fbx";
        const string PassengerControllerPath = "Assets/Passengers/Passenger.controller";
        const string PassengerPrefabPath = "Assets/Passengers/Passenger.prefab";

        /// <summary>
        /// Turns the downloaded Mixamo character into something the generator can drop into a
        /// scene: humanoid rig, a looping walk clip, an animator controller that plays it, and a
        /// prefab with PassengerWalker already on it.
        ///
        /// The clip was exported In Place, so it has no root motion and PassengerWalker keeps
        /// full control of where the figure actually goes.
        /// </summary>
        [MenuItem("Tools/Train Sim/Set Up Passenger Model", priority = 22)]
        public static void SetUpPassengerModel()
        {
            ModelImporter importer = AssetImporter.GetAtPath(PassengerModelPath) as ModelImporter;

            if (importer == null)
            {
                Debug.LogError("[TRAIN SIM] No model at " + PassengerModelPath);
                return;
            }

            importer.animationType = ModelImporterAnimationType.Human;
            importer.importAnimation = true;

            ModelImporterClipAnimation[] clips = importer.defaultClipAnimations;

            if (clips.Length > 0)
            {
                clips[0].name = "Walk";
                clips[0].loopTime = true;
                importer.clipAnimations = clips;
            }

            importer.SaveAndReimport();

            AnimationClip walk = null;

            foreach (Object o in AssetDatabase.LoadAllAssetsAtPath(PassengerModelPath))
            {
                AnimationClip c = o as AnimationClip;

                if (c != null && !c.name.StartsWith("__"))
                {
                    walk = c;
                }
            }

            if (walk == null)
            {
                Debug.LogError("[TRAIN SIM] No walk clip found inside " + PassengerModelPath);
                return;
            }

            AnimatorController controller =
                AnimatorController.CreateAnimatorControllerAtPathWithClip(
                    PassengerControllerPath, walk);

            GameObject model = AssetDatabase.LoadAssetAtPath<GameObject>(PassengerModelPath);
            GameObject instance = (GameObject)PrefabUtility.InstantiatePrefab(model);
            instance.name = "Passenger";

            Animator animator = instance.GetComponent<Animator>();

            if (animator == null)
            {
                animator = instance.AddComponent<Animator>();
            }

            animator.runtimeAnimatorController = controller;
            animator.applyRootMotion = false;

            // The clip drives the legs now, so the hand rolled bone swing is off.
            PassengerWalker walker = instance.AddComponent<PassengerWalker>();
            walker.enableBoneWalk = false;

            PrefabUtility.SaveAsPrefabAsset(instance, PassengerPrefabPath);
            Object.DestroyImmediate(instance);

            AssetDatabase.SaveAssets();

            Debug.Log(
                "[TRAIN SIM] Passenger prefab ready at " + PassengerPrefabPath +
                " using clip " + walk.name + "."
            );
        }

        // ==========================================
        // MEASURING
        // ==========================================

        /// <summary>
        /// Prints the real mesh bounds behind the numbers at the top of the generator. Run this
        /// when something looks like it is floating or sunk, then correct the constants in
        /// Tools/generate_scenes.py rather than dragging objects around.
        /// </summary>
        [MenuItem("Tools/Train Sim/Probe Layout", priority = 20)]
        public static void Probe()
        {
            var sb = new System.Text.StringBuilder();
            sb.AppendLine("===== LAYOUT PROBE =====");

            ProbePrefab(sb, TrainPrefabPath);
            ProbePrefab(sb, RailPrefabPath);
            ProbePrefab(sb, PassengerModelPath);
            ProbePrefab(sb, HitogatasModelPath);

            ProbeTerrainAndPlatforms(sb);

            Debug.Log(sb.ToString());
        }

        static void ProbePrefab(System.Text.StringBuilder sb, string path)
        {
            GameObject prefab = AssetDatabase.LoadAssetAtPath<GameObject>(path);

            if (prefab == null)
            {
                sb.AppendLine("MISSING: " + path);
                return;
            }

            GameObject instance = (GameObject)PrefabUtility.InstantiatePrefab(prefab);
            instance.transform.position = Vector3.zero;
            instance.transform.rotation = Quaternion.identity;

            Bounds bounds = new Bounds(Vector3.zero, Vector3.zero);
            bool first = true;

            foreach (Renderer renderer in instance.GetComponentsInChildren<Renderer>())
            {
                if (first)
                {
                    bounds = renderer.bounds;
                    first = false;
                }
                else
                {
                    bounds.Encapsulate(renderer.bounds);
                }
            }

            sb.AppendLine(System.IO.Path.GetFileNameWithoutExtension(path));
            sb.AppendLine("   size " + bounds.size + "   min " + bounds.min + "   max " + bounds.max);

            Object.DestroyImmediate(instance);
        }

        /// <summary>
        /// The terrain extent matters: the train starts at z = -95 and must not run off the edge
        /// of the ground. Platform surface height decides where the passengers stand.
        /// </summary>
        static void ProbeTerrainAndPlatforms(System.Text.StringBuilder sb)
        {
            Scene scene = EditorSceneManager.OpenScene(StationScenePath, OpenSceneMode.Additive);

            float platformTop = float.MinValue;

            foreach (GameObject root in scene.GetRootGameObjects())
            {
                Terrain terrain = root.GetComponent<Terrain>();

                if (terrain != null && terrain.terrainData != null)
                {
                    Vector3 size = terrain.terrainData.size;
                    Vector3 origin = root.transform.position;

                    sb.AppendLine("Terrain at " + origin + " size " + size);
                    sb.AppendLine("   covers x " + origin.x + " to " + (origin.x + size.x));
                    sb.AppendLine("   covers z " + origin.z + " to " + (origin.z + size.z));
                }

                if (!root.name.StartsWith("cement platform"))
                {
                    continue;
                }

                foreach (Renderer renderer in root.GetComponentsInChildren<Renderer>())
                {
                    // The west platform is the one the passengers board from.
                    if (renderer.bounds.center.x < 0f &&
                        renderer.bounds.max.y > platformTop)
                    {
                        platformTop = renderer.bounds.max.y;
                    }
                }
            }

            sb.AppendLine("west platform surface y = " + platformTop);

            EditorSceneManager.CloseScene(scene, true);
        }
    }
}
